function getModuleState(module){state.modules[module.id]={vocabStreak:0,correctStreak:0,status:"unsicher",variant:0,vocabVariant:0,vocabSeed:Date.now(),exerciseSeed:Date.now()+17,attempts:0,...(state.modules[module.id]||{})};return state.modules[module.id]}
function moduleIndex(id){return modules.findIndex((m)=>m.id===id)}
function isUnlocked(index){return index===0||modules.slice(0,index).every((m)=>getModuleState(m).status==="verstanden")}
function activeModule(){let index=moduleIndex(state.activeModule);if(index<0||!isUnlocked(index)){index=modules.findIndex((_,i)=>isUnlocked(i));state.activeModule=modules[Math.max(0,index)].id}return modules.find((m)=>m.id===state.activeModule)||modules[0]}
function normalize(text){return text.toLowerCase().replace(/[.,!?]/g,"").replace(/\s+/g," ").trim()}
function strip(text){return text.replace(/[.,!?]/g,"").trim()}
function taskGerman(task){return strip(task.replace(/^Schreibe:\s*/,"").replace(/^Zusatz:\s*Schreibe\s*/,"").replace(/^Prüfung:\s*/,"").replace(/^Frage:\s*/,"").replace(/^Antworte:\s*/,"").replace(/^"/,"").replace(/"$/,""))}
function nextSeed(){return Math.floor(Date.now()+Math.random()*1000000)}
function seededRandom(seed){let value=seed%2147483647;if(value<=0)value+=2147483646;return()=>{value=value*16807%2147483647;return(value-1)/2147483646}}
function shuffled(items,seed){const random=seededRandom(seed);const list=[...items];for(let i=list.length-1;i>0;i-=1){const j=Math.floor(random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
function sectionKey(id){return id.match(/^(avsnitt-\d+)/)?.[1]||id}
function getVocab(module){const phraseVocab=module.expected.map((sentence,index)=>[strip(sentence),taskGerman(module.tasks[index]||guessGerman(strip(sentence)))]);const fromExpected=module.expected.flatMap((sentence)=>strip(sentence).split(" ")).filter((w)=>w.length>1).map((sv)=>[sv,guessGerman(sv)]).filter(([,de])=>de);const nounVocab=module.nounVocab||[];const merged=[...nounVocab,...(extraWords[sectionKey(module.id)]||[]),...(extraWords[module.id]||[]),...phraseVocab,...fromExpected,...commonVocab,...filler];const seen=new Set();return merged.filter(([sv,de])=>{const key=sv.toLowerCase();if(!de||seen.has(key))return false;seen.add(key);return true}).slice(0,28).map(([sv,de],i)=>({sv,de,hint:hints[i%hints.length]}))}
function guessGerman(sv){const map={Hej:"Hallo","Hej då":"Auf Wiedersehen",Tack:"Danke","Ursäkta":"Entschuldigung","God morgon":"Guten Morgen","God kväll":"Guten Abend","Vi ses":"Wir sehen uns",Ja:"Ja",Nej:"Nein","Varsågod":"Bitte / gern",Förlåt:"Verzeihung",Jag:"Ich",jag:"ich",Du:"Du",du:"du",Han:"Er",han:"er",Hon:"Sie",hon:"sie",det:"es",Vi:"Wir",vi:"wir",De:"Sie",de:"sie",Ni:"Ihr / Sie",ni:"ihr / Sie",heter:"heiße",kommer:"komme",från:"aus",bor:"wohne",talar:"spreche",svenska:"Schwedisch",tyska:"Deutsch",engelska:"Englisch",är:"bin / bist / ist / sind",snäll:"nett",trött:"müde",Schweiz:"Schweiz",Sverige:"Schweden",har:"habe / hat",inte:"nicht",vill:"will / möchte",kan:"kann",lära:"lernen",läser:"lerne / lese",mig:"mich / mir",sig:"sich",lite:"ein bisschen",mycket:"viel",kaffe:"Kaffee",barn:"Kind / Kinder",familj:"Familie",syster:"Schwester",bror:"Bruder",mamma:"Mutter",pappa:"Vater",vän:"Freund",bil:"Auto",Bilen:"das Auto",hus:"Haus",Huset:"das Haus",frukost:"Frühstück",vatten:"Wasser",bröd:"Brot",mjölk:"Milch",te:"Tee",mat:"Essen",biljett:"Ticket",stationen:"Bahnhof",gata:"Straße",stad:"Stadt",karta:"Karte",höger:"rechts",vänster:"links",nära:"nahe",idag:"heute",imorgon:"morgen",åtta:"acht",klockan:"Uhr",kostar:"kostet",kronor:"Kronen",tavla:"Wandtafel",bord:"Tisch",stol:"Stuhl",lampa:"Lampe",dörr:"Tür",fönster:"Fenster",säng:"Bett",bok:"Buch",penna:"Stift",papper:"Papier",kök:"Küche",rum:"Zimmer",soffa:"Sofa",hylla:"Regal",dator:"Computer",telefon:"Telefon",nyckel:"Schlüssel",väska:"Tasche",jacka:"Jacke",sko:"Schuh",tallrik:"Teller",glas:"Glas",kopp:"Tasse",sked:"Löffel",gaffel:"Gabel",kniv:"Messer",cykel:"Fahrrad"};return map[sv]||""}
function getVocabRound(module){const s=getModuleState(module);return shuffled(getVocab(module),s.vocabSeed+s.vocabVariant*97).slice(0,10)}
function unique(list){return [...new Set(list.filter(Boolean))]}
function getChoices(correct,module,index=0){const s=getModuleState(module);const all=unique([...getVocab(module),...filler.map(([sv,de])=>({sv,de}))].map((x)=>x.de).filter((de)=>de!==correct.de));return shuffled([correct.de,...shuffled(all,s.vocabSeed+index*31).slice(0,3)],s.vocabSeed+index*53)}
function exercise(module){const s=getModuleState(module);const basePairs=module.tasks.map((task,index)=>({task,expected:module.expected[index]}));const targetSize=module.checkpoint?6:5;const extras=shuffled(getVocab(module).filter((item)=>!module.expected.some((sentence)=>normalize(sentence).includes(normalize(item.sv)))),s.exerciseSeed+s.variant*131).slice(0,Math.max(0,targetSize-basePairs.length)).map((item)=>({task:`Zusatz: Schreibe "${item.de}".`,expected:item.sv}));const round=shuffled([...basePairs,...extras],s.exerciseSeed+s.variant*173).slice(0,targetSize);return {tasks:round.map((item)=>item.task),expected:round.map((item)=>item.expected)}}
function render(){const module=activeModule();const s=getModuleState(module);const vocab=s.vocabStreak<1;byId("moduleTag").textContent=module.tag;byId("moduleTitle").textContent=module.title;byId("topicStatus").textContent=vocab?`Voci ${s.vocabStreak}/1`:s.status;byId("difficulty").textContent=vocab?"Voci":"A1";byId("todayCount").textContent=state.today;byId("masteredCount").textContent=Object.values(state.modules).filter((m)=>m.status==="verstanden").length;byId("errorCount").textContent=state.totalErrors;renderModules();if(vocab){byId("taskTitle").textContent=`Voci vor "${module.title}"`;byId("taskList").innerHTML="<li>Beantworte 10 Wörter fehlerfrei.</li><li>Erst danach wird die Satzübung freigeschaltet.</li>"+bookAudioPanel(module);byId("answerForm").classList.add("hidden");byId("vocabForm").classList.remove("hidden");renderVocab(module)}else{const ex=exercise(module);byId("taskTitle").textContent=module.checkpoint?"A1-Checkpoint: gemischte Prüfung.":"Übung: ein längerer Durchgang.";byId("taskList").innerHTML=ex.tasks.map((t)=>`<li>${t}</li>`).join("")+bookAudioPanel(module);byId("vocabForm").classList.add("hidden");byId("answerForm").classList.remove("hidden")}renderFlowButton()}
function renderModules(){byId("moduleList").innerHTML=modules.map((m,i)=>{const s=getModuleState(m);const locked=!isUnlocked(i);return `<button class="module-button${m.id===state.activeModule?" active":""}${s.status==="verstanden"?" mastered":""}${locked?" locked":""}" data-module="${m.id}" type="button" ${locked?"disabled":""}>${m.title}<span>${locked?"Gesperrt · ":""}Voci ${s.vocabStreak}/1 · Übung ${Math.min(s.correctStreak,1)}/1 · ${s.status}</span></button>`}).join("")}
