function drillBlock(title,lines){const clean=[...new Set(lines.filter(Boolean))].slice(0,6);if(!clean.length)return "";return `<div class="feedback-item warn"><strong>${title}</strong><ol>${clean.map((line)=>`<li><em>${line}</em><br>Schreibe diesen Ausdruck 3x laut und sauber ab. Danach erst neu versuchen.${audioRows([line])}</li>`).join("")}</ol></div>`}
