function checkVocab(module){const items=getVocabRound(module);const mistakes=[];items.forEach((item,i)=>{const selected=byId("vocabForm").querySelector(`input[name="vocab-${i}"]:checked`);if(!selected||selected.value!==item.de)mistakes.push({...item,selected:selected?.value||"keine Antwort"})});return {passed:mistakes.length===0,mistakes,items}}
function textSentences(text){return text.split(/\n|[.!?]+/).map((line)=>line.trim()).filter(Boolean)}
