function analyzeCoachIssues(text,expected=[]){const issues=[];const raw=text;const input=normalize(text);coachRules.forEach((rule)=>{if(rule.pattern.test(raw)||rule.pattern.test(input))issues.push({key:rule.key,fix:rule.fix,explain:rule.explain})});pluralPairs.forEach(([singular,plural])=>{const singularHit=new RegExp(`\\b(två|tre|fyra|fem|sex|sju|åtta|nio|tio|elva|tolv|tretton|fjorton|femton|tjugo|trettio|hundra)\\s+${singular}\\b`,"i").test(input);if(singular!==plural&&singularHit)issues.push({key:`plural-${plural}`,fix:plural,explain:`Nach Zahlen ab 2 brauchst du hier den Plural: ${singular} -> ${plural}.`})});if(input.includes("det har"))issues.push({key:"har-det-finns",fix:"det finns",explain:"det har ist hier deutsch gedacht. Für 'es gibt' nutzt du det finns."});if(expected.some((x)=>normalize(x).startsWith("finns det"))&&input.includes("det finns"))issues.push({key:"question-order",fix:"Finns det ...?",explain:"Bei Ja/Nein-Fragen steht das Verb zuerst: Finns det ...?"});return uniqueIssues(issues)}
function uniqueIssues(issues){const seen=new Set();return issues.filter((issue)=>{if(seen.has(issue.key))return false;seen.add(issue.key);return true})}
function reviewCriteria(text){const input=normalize(text);const lines=textSentences(text);return [
  {label:"mindestens 5 kurze Sätze",ok:lines.length>=5},
  {label:"Name oder Wohnort genannt",ok:/\b(heter|bor|kommer)\b/.test(input)},
  {label:"mindestens eine Verneinung mit inte",ok:input.split(" ").includes("inte")},
  {label:"mindestens einmal kan oder vill",ok:input.split(" ").some((w)=>w==="kan"||w==="vill")},
  {label:"ein A1-Thema wie Familie, Arbeit, Wohnen, Essen oder Reise",ok:/\b(familj|mamma|pappa|syster|bror|arbete|jobbar|arbetar|lägenhet|rum|kaffe|frukost|resa|biljett)\b/.test(input)}
]}
function checkAnswer(text,ex,module){const input=normalize(text);const issues=analyzeCoachIssues(text,ex.expected);if(module.id==="a1review"){const criteria=reviewCriteria(text);const passed=criteria.every((item)=>item.ok)&&issues.length===0;const missing=criteria.filter((item)=>!item.ok).map((item)=>item.label);return {passed,hits:criteria.filter((item)=>item.ok).map((item)=>item.label),missing,criteria,issues}}const hits=ex.expected.filter((x)=>hasExpected(input,x));const missing=ex.expected.filter((x)=>!hasExpected(input,x));const passed=missing.length===0&&issues.length===0;return {passed,hits,missing,criteria:[],issues}}
function applyVocab(result,module){const s=getModuleState(module);state.today+=1;s.attempts+=1;if(result.passed){s.vocabStreak=1;if(s.status==="unsicher")s.status="Voci bestanden";s.exerciseSeed=nextSeed()}else{s.vocabStreak=0;s.vocabVariant+=1;s.vocabSeed=nextSeed();state.totalErrors+=Math.max(1,result.mistakes.length);state.errors.Voci=(state.errors.Voci||0)+result.mistakes.length}saveState()}
function updatePatternMemory(result,module){state.patterns=state.patterns||{};(result.issues||[]).forEach((issue)=>{const item=state.patterns[issue.key]||{status:"new",correct:0,errors:0,last:null};item.errors+=1;item.status=item.errors>=2?"shaky":"practicing";item.last=Date.now();state.patterns[issue.key]=item;state.errors[issue.key]=(state.errors[issue.key]||0)+1});if(result.passed){const key=`module-${module.id}`;const item=state.patterns[key]||{status:"new",correct:0,errors:0,last:null};item.correct+=1;item.status=item.correct>=3?"mastered":item.correct>=2?"stable":"practicing";item.last=Date.now();state.patterns[key]=item}}
function applyAnswer(result,module){const s=getModuleState(module);state.today+=1;s.attempts+=1;updatePatternMemory(result,module);if(result.passed){s.correctStreak=1;s.status="verstanden"}else{s.exerciseSeed=nextSeed();state.totalErrors+=1;state.errors.Satzbau=(state.errors.Satzbau||0)+1;s.status="unsicher"}saveState();return result.passed&&s.status==="verstanden"}
function showVocabFeedback(result){const fb=byId("feedback");if(result.passed){fb.innerHTML=`<h3>Voci-Korrektur</h3><div class="feedback-item ok"><strong>Voci sitzt.</strong>Alle 10 Wörter korrekt. Die Satzübung ist frei.</div><div class="feedback-item ok"><strong>Audio freigeschaltet</strong>${audioRows(result.items.map((x)=>x.sv))}</div>${renderFeedbackAction(true)}`}else{fb.innerHTML=`<h3>Voci-Korrektur</h3>${restartNotice()}<div class="feedback-item warn"><strong>Voci verkackt.</strong>Hier sind die genauen Treffer ins Knie. Erst drillen, dann neu starten.</div>${result.mistakes.map((x)=>`<div class="feedback-item bad"><strong>${x.sv}</strong>Deine Wahl: ${x.selected}<br>Korrekt: <em>${x.de}</em></div>`).join("")}${drillBlock("Kurz-Drill vor dem Neustart",result.mistakes.flatMap((x)=>[`${x.sv} = ${x.de}`,x.sv]))}${renderFeedbackAction(false)}`}fb.classList.remove("hidden")}
function issueBlock(issues){if(!issues?.length)return "";return `<div class="feedback-item warn"><strong>Coach-Korrektur</strong>${issues.map((issue)=>`<br><em>${issue.fix}</em>: ${issue.explain}`).join("")}</div>`}
function coachRepeatLines(result,ex){const lines=[...(result.missing||[])];(result.issues||[]).slice(0,2).forEach((issue)=>{if(issue.key==="talar-tala")lines.push("Jag talar svenska.","Jag kan tala svenska.");else if(issue.key==="bor-bo")lines.push("Jag bor i Schweiz.","Jag vill bo i Sverige.");else if(issue.key==="inte-position")lines.push("Jag talar inte svenska.","Jag kan inte tala svenska.");else if(issue.key==="har-det-finns")lines.push("Det finns tre biljetter.","Jag har en biljett.");else lines.push(issue.fix)});return unique(lines).slice(0,3)}
function showAnswerFeedback(result,module,ex){const s=getModuleState(module);const fb=byId("feedback");const msg=result.passed?winMessages[Math.floor(Math.random()*winMessages.length)]:roastMessages[Math.floor(Math.random()*roastMessages.length)];let html=`<h3>Korrektur</h3><div class="feedback-item ${result.passed?"ok":"warn"}"><strong>${msg}</strong>${result.passed?"Kurzer Durchgang bestanden.":"Diese Runde zählt als nicht bestanden."}</div>`;if(result.criteria?.length)html+=`<div class="feedback-item ${result.passed?"ok":"warn"}"><strong>A1-Kriterien</strong>${result.criteria.map((item)=>`<br>${item.ok?"✓":"✗"} ${item.label}`).join("")}</div>`;html+=issueBlock(result.issues);if(!result.passed)html+=restartNotice();if(result.missing.length)html+=`<div class="feedback-item bad"><strong>Fehlt oder zu anders formuliert</strong>${result.missing.map((x)=>`<br><em>${x}</em>`).join("")}</div>`;const repeat=coachRepeatLines(result,ex);if(!result.passed&&repeat.length)html+=drillBlock("Jetzt nur diese Mini-Wiederholung",repeat);if(result.passed)html+=`<div class="feedback-item ok"><strong>Aussprache freigeschaltet</strong>${audioRows(ex.expected)}</div>`;if(s.status==="verstanden")html+=`<div class="feedback-item ok"><strong>Nächstes Thema bereit</strong>Mit WEITER geht es zur nächsten Kategorie.</div>`;fb.innerHTML=html+renderFeedbackAction(result.passed);fb.classList.remove("hidden")}
function goNext(){const module=activeModule();const s=getModuleState(module);if(lastCheckedMode==="vocab"){if(!lastCheckedPassed){s.vocabVariant+=1;s.vocabSeed=nextSeed()}else{s.exerciseSeed=nextSeed()}}else if(!lastCheckedPassed){s.variant+=1;s.exerciseSeed=nextSeed()}else if(s.correctStreak>=1){const next=moduleIndex(module.id)+1;if(next<modules.length){state.activeModule=modules[next].id;const nextState=getModuleState(modules[next]);nextState.vocabSeed=nextSeed();nextState.exerciseSeed=nextSeed()}}lastCheckedPassed=null;lastCheckedMode=null;byId("answerInput").value="";byId("feedback").classList.add("hidden");saveState();render()}
function refreshVoices(){voices=(speechSynthesis?.getVoices?.()||[]).filter((v)=>/^sv/i.test(v.lang)||/swedish|svenska|bengt/i.test(v.name))}
function voice(){return voices[0]||null}
function speakSwedish(text,speed="normal"){if(!("speechSynthesis" in window)){alert("Dein Browser unterstützt keine Sprachausgabe.");return}refreshVoices();const v=voice();if(!v){alert("Keine schwedische Stimme gefunden. Installiere in Windows eine schwedische Sprache/Stimme oder nutze Edge/Chrome mit einer sv-SE Stimme.");return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="sv-SE";u.voice=v;u.rate=speed==="slow"?.72:.9;u.pitch=1;speechSynthesis.speak(u)}
function celebration(){const c=byId("celebration");c.classList.remove("fly");void c.offsetWidth;c.classList.add("fly");try{const ctx=new (window.AudioContext||window.webkitAudioContext)();[880,1175,1568].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.value=.02;o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.08);o.stop(ctx.currentTime+i*.08+.25)})}catch{}}
async function copyChar(char,button){try{await navigator.clipboard.writeText(char);button.dataset.tooltip="copied";button.classList.add("copied");setTimeout(()=>{button.dataset.tooltip="copy";button.classList.remove("copied")},900)}catch{byId("answerInput").focus();document.execCommand("insertText",false,char)}}
function applyTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem("svenska-a1-theme",theme);const btn=byId("themeBtn");if(btn)btn.textContent=theme==="dark"?"Hell":"Dunkel"}
function initTheme(){const saved=localStorage.getItem("svenska-a1-theme");const preferred=window.matchMedia?.("(prefers-color-scheme: dark)")?.matches?"dark":"light";applyTheme(saved||preferred)}
byId("moduleList").addEventListener("click",(e)=>{const b=e.target.closest("[data-module]");if(!b||b.disabled)return;state.activeModule=b.dataset.module;lastCheckedPassed=null;lastCheckedMode=null;byId("feedback").classList.add("hidden");saveState();render()});
byId("vocabForm").addEventListener("submit",(e)=>{e.preventDefault();const m=activeModule();const r=checkVocab(m);applyVocab(r,m);lastCheckedPassed=r.passed;lastCheckedMode="vocab";render();showVocabFeedback(r);renderFlowButton()});
byId("answerForm").addEventListener("submit",(e)=>{e.preventDefault();const text=byId("answerInput").value.trim();if(!text)return;const m=activeModule();const ex=exercise(m);const r=checkAnswer(text,ex,m);const mastered=applyAnswer(r,m);lastCheckedPassed=r.passed;lastCheckedMode="exercise";render();showAnswerFeedback(r,m,ex);renderFlowButton();if(mastered)celebration()});
byId("nextBtn").addEventListener("click",goNext);byId("feedback").addEventListener("click",(e)=>{const flow=e.target.closest("[data-feedback-flow]");if(flow)return goNext();const speak=e.target.closest("[data-speak]");if(speak)speakSwedish(decodeURIComponent(speak.dataset.speak),speak.dataset.speed||"normal")});
document.querySelectorAll("[data-copy-char]").forEach((b)=>{b.addEventListener("click",()=>copyChar(b.dataset.copyChar,b));b.addEventListener("mouseenter",()=>copyChar(b.dataset.copyChar,b))});
byId("themeBtn")?.addEventListener("click",()=>applyTheme(document.documentElement.dataset.theme==="dark"?"light":"dark"));
byId("resetBtn").addEventListener("click",()=>{if(!confirm("Fortschritt wirklich zurücksetzen?"))return;localStorage.removeItem("svenska-a1-state");state=loadState();lastCheckedPassed=null;lastCheckedMode=null;byId("answerInput").value="";byId("feedback").classList.add("hidden");render()});
initTheme();resetLegacy();refreshVoices();if("speechSynthesis" in window)speechSynthesis.onvoiceschanged=refreshVoices;render();
